{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "Previous studies have identified diabetes as an independent risk factor for poor prognosis of coronavirus ● disease-2019 (COVID-19)\n...\nHowever, some of the findings are still conflicting, imprecisely estimated or affected by risk of bias, such as confounding.",
      "reason": "The manuscript describes the current state of knowledge (diabetes as a risk factor) and highlights important uncertainties including conflicting findings, imprecision, and risk of bias in existing studies."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "To provide the best available evidence for the identification of risk phenotypes of diabetes in association with COVID-19 severity and death, a systematic review and meta-analysis is needed that summarises the findings, reveals more robust estimates, considers risk of bias and evaluates the certainty of evidence.",
      "reason": "The authors explicitly explain the importance and need for conducting this systematic review and meta-analysis to summarise findings, obtain more robust estimates, consider risk of bias, and evaluate certainty of evidence."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "Several systematic reviews and meta-analyses on diabetes and COVID19 prognosis have observed an approximately two- to threefold increased risk of mortality due to COVID-19 for people with diabetes compared with people without diabetes [6 - 14].\n...\nTherefore, we are conducting a living systematic review and meta-analysis on the associations between phenotypes of diabetes and confirmed SARS-CoV-2 infection with relation to COVID-19 death and severity.",
      "reason": "The manuscript acknowledges existing systematic reviews and meta-analyses and explains the rationale and need for the current (living) review in that context."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review concerns prognostic associations of diabetes phenotypes with COVID-19 outcomes, not effects of interventions; no mechanism of action of an intervention is relevant or described."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not address complex interventions or delivery contexts and does not present or require a logic model; this reporting item is not applicable."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
