      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Studies without primary clinical data (including modelling studies), editorials, letters, commentaries, reviews, articles not in English and guidelines were excluded.",
      "reason": "Language restriction (articles not in English excluded) and exclusion of non-primary clinical data are specified, but other report characteristics such as dissemination year or explicit publication/report status criteria are not fully described (although search date is provided elsewhere), so reporting is partial."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "No risk estimates",
