    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "For similar exposures (with similar reference groups [e.g., men vs women; obese vs normal weight; use of insulin: yes vs no; pre-existing comorbidities: yes vs no]), meta-analyses were conducted separately for the two outcomes: death and severity.",
      "reason": "The manuscript specifies how studies were grouped for synthesis (examples of reference groups) and that meta-analyses were conducted separately for the two outcomes, linking groups to the review comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationale is provided in the retrieved evidence for notable eligibility restrictions (e.g., the reason for excluding non-English articles or other exclusions); the manuscript lists exclusions but does not explain the justification for these restrictions."
    }
  ],
  "confidence": 85
